use crate::{config::{ensure_data_dir,Settings},message,state::State,weather,wechat::WechatClient};
use chrono::{DateTime,Duration,NaiveDate,NaiveTime,TimeZone,Utc}; use chrono_tz::Tz; use std::time::Duration as StdDuration; use tokio::time::sleep; use tracing::{error,info,warn};
pub fn preview(s:&Settings,slot:&str)->Result<(),Box<dyn std::error::Error>>{let tz:Tz=s.timezone.parse()?;let d=Utc::now().with_timezone(&tz).date_naive();let p:Vec<_>=s.recipients.iter().map(|r|message::build(s,r,slot,d,None)).collect();println!("{}",serde_json::to_string_pretty(&p)?);Ok(())}
pub async fn send_once(s:&Settings,slot:&str)->Result<(),Box<dyn std::error::Error>>{let now=local_now(&s.timezone)?;send_slot(s,slot,now.date_naive()).await}
pub async fn run_service(s:Settings)->Result<(),Box<dyn std::error::Error>>{ensure_data_dir(&s.data_dir)?;loop{let now=local_now(&s.timezone)?;for(slot,(h,m)) in [("morning",s.morning_time),("evening",s.evening_time)]{let scheduled=now.date_naive().and_time(NaiveTime::from_hms_opt(h,m,0).unwrap());if now.naive_local()>=scheduled{send_slot(&s,slot,now.date_naive()).await?;}}let wait=next_wake(&s,now)?;sleep(StdDuration::from_secs(wait.max(1)as u64)).await;}}
async fn send_slot(s:&Settings,slot:&str,date:NaiveDate)->Result<(),Box<dyn std::error::Error>>{let db=s.data_dir.join("deliveries.sqlite3");let state=State::open(&db)?;let client=WechatClient::new(s.timeout_seconds)?;let token=match client.token(s).await{Ok(v)=>v,Err(e)=>{error!(slot,error=%e,"failed to obtain access token");return Ok(());}};for r in &s.recipients{if !state.claim(date,slot,&r.openid)?{continue;}let weather=if s.weather_enabled{match weather::fetch(s).await {Ok(value)=>Some(value),Err(e)=>{warn!(error=%e,"weather lookup failed");None}}}else{None};let p=message::build(s,r,slot,date,weather.as_deref());match client.send(&token,&p).await{Ok(id)=>{state.finish(date,slot,&r.openid,"sent")?;info!(slot,openid=%r.openid,msgid=id,"message sent");},Err(e)=>{state.finish(date,slot,&r.openid,"unknown")?;warn!(slot,openid=%r.openid,error=%e,"message result unknown; no automatic retry");}}}Ok(())}
fn local_now(tz:&str)->Result<DateTime<Tz>,Box<dyn std::error::Error>>{let tz:Tz=tz.parse()?;Ok(Utc::now().with_timezone(&tz))}
fn next_wake(s:&Settings,now:DateTime<Tz>)->Result<i64,Box<dyn std::error::Error>>{let mut c=Vec::new();for off in 0..=1{let d=now.date_naive()+Duration::days(off);for(_, (h,m)) in [("morning",s.morning_time),("evening",s.evening_time)]{let x=now.timezone().from_local_datetime(&d.and_time(NaiveTime::from_hms_opt(h,m,0).unwrap())).single().ok_or("ambiguous schedule")?;if x>now{c.push(x);}}}Ok((c.into_iter().min().unwrap()-now).num_seconds())}
